head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = ""; // R=접수, H = 이력, N : 신규
scwin.clickDisclsMainDocFormCd = "";
scwin.clickBzProcsNoRecent = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fr_SecuGrpId = SECUGRP_ID_PF;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.recvListSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISU_CD_onclick
 * @description img_ISU_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsuCd;
        scwin.fn_SetPar = scwin.setParIsuCd;
        $c.lc.fn_PopFindIsu(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09304.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.allListSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_CD.focus();
            return;
        }
        await scwin.openDetailMng(-1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF09304.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "PF변경상장내역", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09304.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_Recv_OnClick
 * @description grd_Recv 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Recv_OnClick = async function(row, colid) {
    try {
        scwin.clickDisclsMainDocFormCd = dts_Recv.getCellData(row, "DISCLS_MAINDOC_FORM_CD");
        scwin.clickBzProcsNoRecent = dts_Recv.getCellData(row, "BZ_PROCS_NO_RECENT");
        txb_ISU_CD.setValue(dts_Recv.getCellData(row, "ISU_CD"));
        txb_ISU_NM.setValue(dts_Recv.getCellData(row, "ISU_KOR_NM"));
        await scwin.listSync();
        await scwin.listBenfEstbDDCheck(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.grd_Recv_OnClick" });
    }
};

/**
 * @method
 * @name grd_Recv_OnDblClick
 * @description grd_Recv 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Recv_OnDblClick = function(row, colid) {
    try {
        scwin.clickBzProcsNoRecent = dts_Recv.getCellData(row, "BZ_PROCS_NO_RECENT");
        $c.elw.fn_OpenDetailRecv(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09304.grd_Recv_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetailMng(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_Recv_OnLoadError
 * @description dts_Recv 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Recv_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Recv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.dts_Recv_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09304.dts_List_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name recvListSync
 * @description recv List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvListSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF09304.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_PF_RECV;
    const sbmOptions = {
        id : "sbm_dts_Recv",
        action : "/pf/PfLstinvstg.do",
        ref : "",
        target : "dts_Recv=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF09304.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_PF_HIST + "&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/pf/PfLstinvstg.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        btn_Search.trigger("onclick");
    }
};

/**
 * @method
 * @name allListSync
 * @description all List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allListSync = async function() {
    await scwin.recvListSync();
    await scwin.listSync();
};

/**
 * @method
 * @name openDetailRecv
 * @description open Detail Recv 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailRecv = async function(row) {
    scwin.vOpenTyp = "R";
    scwin.vAcptNo = dts_Recv.getCellData(row, "ACPT_NO");
    scwin.vIsurCd = dts_Recv.getCellData(row, "ISUR_CD");
    if (scwin.clickDisclsMainDocFormCd === "69780") // 변경상장 취소 서식이면

    {
        await scwin.openPopupCancel();
    } else {
        await scwin.openPopup();
    }
};

/**
 * @method
 * @name openDetailMng
 * @description open Detail Mng 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailMng = async function(row) {
    scwin.vAcptNo = ""; // 초기화
    if (row > 0) {
        // 그리드에서 선택시
        scwin.vOpenTyp = "H";
        scwin.setBzProcsNo(row);
    } else {
        // 신규버튼 선택시
        scwin.vOpenTyp = "N";
        scwin.clickBzProcsNo = ""; // 초기화

    }
    await scwin.openPopup();
};

/**
 * @method
 * @name openPopupCancel
 * @description open Popup Cancel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPopupCancel = async function() {
    const options = {
        id: "ULDSTF09321",
        title: "상장형 수익증권 변경상장 취소",
        type: "browserPopup",
        width: 705 + 35,
        height: 270 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/pf/ULDSTF09321.gfm", options);
};

/**
 * @method
 * @name openPopup
 * @description open Popup 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPopup = async function() {
    const options = {
        id: "ULDSTF09306",
        title: "상장형 수익증권 변경상장 관리",
        type: "browserPopup",
        width: 705 + 35,
        height: 270 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/pf/ULDSTF09306.gfm", options);
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
    scwin.vIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name listBenfEstbDDCheck
 * @description jackal_11.11.01
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listBenfEstbDDCheck = async function(row) {
    // jackal_11.11.01
    if (scwin.clickDisclsMainDocFormCd !== "69780") // 변경상장 취소이 아니면

    {
        const beDD = dts_Recv.getCellData(row, "BENFCERT_ESTBREPUR_DD");
        const LiDD = dts_Recv.getCellData(row, "LIST_DD");
        // alert('beDD='+beDD+' LiDD='+LiDD);
        if (LiDD <= beDD) await $c.win.alert('변경상장 예정일 및 설정 또는 환매일을 확인해 주시기 바랍니다.');
    }
};
